solution.style.css:
body {
  margin: 0;
  font-family: system-ui, sans-serif;
}

.header {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px 32px;
}

.nav {
  display: flex;
  gap: 16px;
  margin-left: auto;
}

@media (max-width: 600px) {
  .header {
    flex-direction: column;
    align-items: flex-start;
    padding: 16px;
  }
  .nav {
    flex-direction: column;
    margin-left: 0;
    gap: 8px;
  }
}

tests:
test('Шапка размечена тегом <header>', () => {
  expect($('header'), 'На странице нет элемента <header>')
})

test('В шапке есть логотип с текстом «Фишт»', () => {
  const logo = $('header .logo')
  expect(logo, 'В <header> нет элемента с классом logo')
  expect(logo.textContent.includes('Фишт'), 'В логотипе нет текста «Фишт»')
})

test('В шапке есть меню <nav> с тремя ссылками', () => {
  const links = $$('header nav a')
  expect($('header nav'), 'В <header> нет <nav>')
  expect(links.length === 3, `В меню ссылок: ${links.length}, а нужно 3`)
})

test('У каждой ссылки меню есть адрес', () => {
  const empty = $$('header nav a').filter((a) => !a.getAttribute('href'))
  expect(empty.length === 0, `Без href: ${empty.map((a) => a.textContent.trim()).join(', ')}`)
})

test('Есть кнопка «Записаться в поход»', () => {
  const cta = $('.cta')
  expect(cta, 'Нет элемента с классом cta')
  expect(/записаться/i.test(cta.textContent), 'На кнопке нет слова «Записаться»')
})

test('На компьютере логотип и меню в одну строку', () => {
  expect($('header .logo') && $('header nav'), 'Сначала нужны логотип и меню внутри <header>')
  const logo = $('header .logo').getBoundingClientRect()
  const nav = $('header nav').getBoundingClientRect()
  const sameLine = nav.top < logo.bottom && logo.top < nav.bottom
  expect(sameLine, 'Меню стоит под логотипом — сделайте шапку строкой (например, display: flex)')
})

test('На телефоне ссылки меню друг под другом', { width: 375 }, () => {
  const links = $$('header nav a').map((a) => a.getBoundingClientRect())
  expect(links.length === 3, 'В меню не три ссылки')
  const stacked = links.every((r, i) => i === 0 || r.top >= links[i - 1].bottom - 1)
  expect(stacked, 'На ширине 375 px ссылки стоят в строку — поставьте их в колонку через @media')
})

test('На телефоне шапка не вылезает за край экрана', { width: 375 }, () => {
  expect(document.documentElement.scrollWidth <= 375, `Ширина страницы ${document.documentElement.scrollWidth} px — появилась горизонтальная прокрутка`)
})
